#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int y, c, f, cost;
    Edge() {}
    Edge(int y, int c, int f, int cost) : y(y), c(c), f(f), cost(cost) {}
};

vector<Edge> all_edges;
const int MAXNODES = 14043;
vector<int> adjacency[MAXNODES];

long long total_cost = 0;
long long dist_array[MAXNODES];
int parent_node[MAXNODES], parent_edge[MAXNODES], in_queue_flag[MAXNODES];

const long long INF_VAL = 1e18;
int s_node = MAXNODES - 2;
int t_node = MAXNODES - 1;

int get_capacity(int idx) {
    return all_edges[idx].c - all_edges[idx].f;
}

void find_min_cost_flow() {
    for (int i = 0; i < MAXNODES; i++) {
        dist_array[i] = INF_VAL;
        parent_node[i] = -1;
        parent_edge[i] = -1;
        in_queue_flag[i] = 0;
    }
    dist_array[s_node] = 0;
    queue<int> q;
    q.push(s_node);
    in_queue_flag[s_node] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        in_queue_flag[u] = 0;
        for (auto e_idx : adjacency[u]) {
            if (get_capacity(e_idx) == 0) continue;
            int cst = all_edges[e_idx].cost;
            int v = all_edges[e_idx].y;
            if (dist_array[v] > dist_array[u] + cst) {
                dist_array[v] = dist_array[u] + cst;
                parent_node[v] = u;
                parent_edge[v] = e_idx;
                if (in_queue_flag[v] == 0) {
                    in_queue_flag[v] = 1;
                    q.push(v);
                }
            }
        }
    }
    int current = t_node;
    while (current != s_node) {
        all_edges[parent_edge[current]].f++;
        all_edges[parent_edge[current] ^ 1].f--;
        current = parent_node[current];
    }
    total_cost += dist_array[t_node];
}

void connect(int from, int to, int cap, int cst) {
    adjacency[from].push_back(all_edges.size());
    all_edges.emplace_back(to, cap, 0, cst);
    adjacency[to].push_back(all_edges.size());
    all_edges.emplace_back(from, 0, 0, -cst);
}

int main() {
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    for (int i = 0; i < k; i++) {
        int x; cin >> x;
        connect(s_node, x, 1, 0);
    }
    int tt = 101;
    for (int i = 0; i < tt; i++)
        connect(1 + i * n, t_node, k, i * c);
    for (int i = 0; i < m; i++) {
        int x, y; cin >> x >> y;
        for (int j = 0; j < tt - 1; j++) {
            connect(x + j * n, y + j * n + n, 1, d * (j * 2 + 1));
            connect(y + j * n, x + j * n + n, 1, d * (j * 2 + 1));
        }
    }
    for (int i = 0; i < n; i++)
        for (int j = 0; j < tt - 1; j++)
            connect(i + j * n, i + j * n + n, k, 0);
    for (int i = 0; i < k; i++)
        find_min_cost_flow();
    cout << total_cost << endl;
}
